import { test, expect } from '@playwright/test';

test.describe('Screen Reader Error Message Announcements', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <form id="testForm">
        <div>
          <label for="email">Email:</label>
          <input type="email" id="email" aria-describedby="emailError" />
          <div id="emailError" role="alert" aria-live="polite" style="display:none; color: red;">
            Please enter a valid email address
          </div>
        </div>
        <div>
          <label for="password">Password:</label>
          <input type="password" id="password" aria-describedby="passwordError" />
          <div id="passwordError" role="alert" aria-live="assertive" style="display:none; color: red;">
            Password must be at least 8 characters
          </div>
        </div>
        <button type="submit">Submit</button>
      </form>
    `);
  });

  test('should announce email validation error to screen readers', async ({ page }) => {
    const emailInput = page.getByLabel('Email:');
    const emailError = page.getByRole('alert').first();

    // Initially error should be hidden
    await expect(emailError).toHaveCSS('display', 'none');

    // Trigger validation error
    await emailInput.fill('invalid-email');
    await emailInput.blur();

    // Show error message
    await page.locator('#emailError').evaluate(el => {
      (el as HTMLElement).style.display = 'block';
    });

    // Verify error is visible and has proper accessibility attributes
    await expect(emailError).toBeVisible();
    await expect(emailError).toHaveAttribute('role', 'alert');
    await expect(emailError).toHaveAttribute('aria-live', 'polite');

    // Verify the input has aria-describedby pointing to error
    await expect(emailInput).toHaveAttribute('aria-describedby', 'emailError');

    // Verify error text content
    await expect(emailError).toContainText('Please enter a valid email address');
  });

  test('should announce password validation error with assertive priority', async ({ page }) => {
    const passwordInput = page.getByLabel('Password:');
    const passwordError = page.getByRole('alert').nth(1);

    // Initially error should be hidden
    await expect(passwordError).toHaveCSS('display', 'none');

    // Trigger validation error
    await passwordInput.fill('short');
    await passwordInput.blur();

    // Show error message
    await page.locator('#passwordError').evaluate(el => {
      (el as HTMLElement).style.display = 'block';
    });

    // Verify error is visible and has proper accessibility attributes
    await expect(passwordError).toBeVisible();
    await expect(passwordError).toHaveAttribute('role', 'alert');
    await expect(passwordError).toHaveAttribute('aria-live', 'assertive');

    // Verify the input has aria-describedby pointing to error
    await expect(passwordInput).toHaveAttribute('aria-describedby', 'passwordError');

    // Verify error text content
    await expect(passwordError).toContainText('Password must be at least 8 characters');
  });

  test('should clear error announcement when input becomes valid', async ({ page }) => {
    const emailInput = page.getByLabel('Email:');
    const emailError = page.getByRole('alert').first();

    // Show initial error
    await page.locator('#emailError').evaluate(el => {
      (el as HTMLElement).style.display = 'block';
    });
    await expect(emailError).toBeVisible();

    // Enter valid email
    await emailInput.fill('valid@example.com');

    // Hide error message
    await page.locator('#emailError').evaluate(el => {
      (el as HTMLElement).style.display = 'none';
    });

    // Verify error is hidden
    await expect(emailError).toHaveCSS('display', 'none');

    // Verify input still has aria-describedby for accessibility context
    await expect(emailInput).toHaveAttribute('aria-describedby', 'emailError');
  });

  test('should maintain accessibility attributes on error elements', async ({ page }) => {
    const allAlerts = page.getByRole('alert');

    // Verify all alert elements have required accessibility attributes
    const alertCount = await allAlerts.count();
    expect(alertCount).toBe(2);

    for (let i = 0; i < alertCount; i++) {
      const alert = allAlerts.nth(i);
      await expect(alert).toHaveAttribute('role', 'alert');

      // Verify aria-live attribute is present
      const ariaLive = await alert.getAttribute('aria-live');
      expect(['polite', 'assertive']).toContain(ariaLive);
    }
  });
});
